{"file_path":"/tmp/claude-0/-home-user-deepseek-harness/f53f80cc-1f77-5d02-a862-99d59ffabdce/scratchpad/bench/runs/e1-sonnet-vs-opus-t5/cell-5R6jLh/src/address.js","content":"// Address parsing and column/row utilities.

// A "word" from the formula lexer is letters+ digits* -- split it apart.
export function splitWord(word) {
  const m = /^([A-Za-z]+)([0-9]*)$/.exec(word)
  if (!m) return null
  return { letters: m[1], digits: m[2] }
}

export function colIndex(letters) {
  let idx = 0
  const upper = letters.toUpperCase()
  for (let i = 0; i < upper.length; i++) {
    idx = idx * 26 + (upper.charCodeAt(i) - 64)
  }
  return idx
}

export function colLetters(idx) {
  let n = idx
  let s = ''
  while (n > 0) {
    const rem = (n - 1) % 26
    s = String.fromCharCode(65 + rem) + s
    n = Math.floor((n - 1) / 26)
  }
  return s
}

// Determine whether letters/digits describe an in-range address.
export function partsInRange(letters, digits) {
  if (letters.length < 1 || letters.length > 2) return false
  if (digits.length < 1 || digits.length > 3) return false
  const row = parseInt(digits, 10)
  return row >= 1
}

// Parse an address-shaped word into {col, row, inRange, canonical} form.
export function parseAddressWord(word) {
  const parts = splitWord(word)
  if (!parts) return null
  const { letters, digits } = parts
  const inRange = partsInRange(letters, digits)
  if (!inRange) return { inRange: false }
  const row = parseInt(digits, 10)
  const col = colIndex(letters)
  const canonical = letters.toUpperCase() + String(row)
  return { inRange: true, col, row, canonical }
}

// Strict address validation used for declaration lines: the whole token
// must be 1-2 letters followed by 1-3 digits naming a row >= 1.
const STRICT_RE = /^([A-Za-z]{1,2})([0-9]{1,3})$/

export function parseDeclaredAddress(token) {
  const m = STRICT_RE.exec(token)
  if (!m) return null
  const letters = m[1]
  const digits = m[2]
  const row = parseInt(digits, 10)
  if (row < 1) return null
  const col = colIndex(letters)
  const canonical = letters.toUpperCase() + String(row)
  return { col, row, canonical }
}

export function addressToString(col, row) {
  return colLetters(col) + String(row)
}
"}

