    if (ch >= '0' && ch <= '9') {
      let j = i
      while (j < n && body[j] >= '0' && body[j] <= '9') j++
      if (j < n && body[j] === '.') {
        let k = j + 1
        let l = k
        while (l < n && body[l] >= '0' && body[l] <= '9') l++
        if (l > k) {
          tokens.push({ type: 'NUMBER', value: body.slice(i, l) })
          i = l
          continue
        }
        // '.' with no following digits: not part of the number.
        tokens.push({ type: 'NUMBER', value: body.slice(i, j) })
        i = j
        continue
      }
      tokens.push({ type: 'NUMBER', value: body.slice(i, j) })
      i = j
      continue
    }
    if ((ch >= 'A' && ch <= 'Z') || (ch >= 'a' && ch <= 'z')) {
      let j = i
      while (j < n && ((body[j] >= 'A' && body[j] <= 'Z') || (body[j] >= 'a' && body[j] <= 'z'))) j++
      let k = j
      while (k < n && body[k] >= '0' && body[k] <= '9') k++
      tokens.push({ type: 'WORD', value: body.slice(i, k) })
      i = k
      continue
    }
    if (ch === '(') { tokens.push({ type: 'LPAREN' }); i++; continue }
    if (ch === ')') { tokens.push({ type: 'RPAREN' }); i++; continue }
    if (ch === ',') { tokens.push({ type: 'COMMA' }); i++; continue }
    if (ch === ':') { tokens.push({ type: 'COLON' }); i++; continue }
    if (ch === '^') { tokens.push({ type: 'OP', value: '^' }); i++; continue }
    if (ch === '*') { tokens.push({ type: 'OP', value: '*' }); i++; continue }
    if (ch === '/') { tokens.push({ type: 'OP', value: '/' }); i++; continue }
    if (ch === '+') { tokens.push({ type: 'OP', value: '+' }); i++; continue }
    if (ch === '-') { tokens.push({ type: 'OP', value: '-' }); i++; continue }
