import { tokenize, LexError } from './lexer.js'
import { splitWord } from './address.js'

export class ParseError extends Error {}

const COMPARISON_OPS = new Set(['=', '<>', '<', '<=', '>', '>='])
const CALL_ARITY = { SUM: 'many', MIN: 'many', MAX: 'many', COUNT: 'many', AVG: 'many', ABS: 1, IF: 3 }

function isWordOp(word, target) {
  return word.toUpperCase() === target
}

class Parser {
  constructor(tokens) {
    this.tokens = tokens
    this.pos = 0
  }

  peek(offset = 0) {
    return this.tokens[this.pos + offset]
  }

  next() {
    return this.tokens[this.pos++]
  }

  parseFormula() {
    const expr = this.parseExpr()
    if (this.pos !== this.tokens.length) {
      throw new ParseError('trailing tokens')
    }
    return expr
  }

  parseExpr() {
    return this.parseComparison()
  }

  parseComparison() {
    let left = this.parseAdditive()
    for (;;) {
      const t = this.peek()
