/**
 * The command. `node src/cli.js values` prints the value of every cell in the
 * sheet read from standard input, and `node src/cli.js deps` prints the cells
 * each one reads.
 */
import { parseSheet, SheetError } from './sheet.js'
import { Evaluator } from './evaluate.js'
import { collectDeps } from './deps.js'
import { formatValue } from './format.js'
import { parseAddressWord } from './address.js'

function readStdin() {
  const fs = require('node:fs')
  try {
    return fs.readFileSync(0, 'utf8')
  } catch (e) {
    return ''
  }
}

function fail(message) {
  process.stderr.write(message + '\n')
  process.exit(2)
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'values' && args[0] !== 'deps')) {
    fail('error: usage: cli.js values|deps')
    return
  }
  const mode = args[0]

  const input = require('node:fs').readFileSync(0, 'utf8')

  let sheet
  try {
    sheet = parseSheet(input)
  } catch (e) {
    if (e instanceof SheetError) {
      fail(e.message)
      return
    }
    throw e
  }

  const sortedAddrs = [...sheet.cells.keys()].sort((a, b) => {
    const pa = parseAddressWord(a)
    const pb = parseAddressWord(b)
    if (pa.col !== pb.col) return pa.col - pb.col
    return pa.row - pb.row
  })

  const out = []

  if (mode === 'values') {
    const evaluator = new Evaluator(sheet.cells)
    for (const addr of sortedAddrs) {
      const v = evaluator.evalCanonical(addr)
      out.push(`${addr}=${formatValue(v)}`)
    }
  } else {
    const evaluator = new Evaluator(sheet.cells)
    for (const addr of sortedAddrs) {
      const ast = evaluator.getAst(addr)
      const cell = sheet.cells.get(addr)
      let deps = []
      if (cell.content.startsWith('=') && ast !== null) {
        deps = collectDeps(ast)
      }
      out.push(`${addr}: ${deps.join(' ')}`.replace(/: $/, ':'))
    }
  }

  process.stdout.write(out.length > 0 ? out.join('\n') + '\n' : '')
  process.exit(0)
}

main()
"}

